+
+#[test]
+fn stock_model_and_placement_edits_rebuild() {
+    let (world, mut h) = fixture();
+    warm(&world);
+    h.execute(
+        &world,
+        SetStock::new(&world, StockShape::Box { dx: 50.0, dy: 50.0, dz: 30.0 }, Location::default()).expect("stock"),
