+#[test]
+fn setup_machine_and_delete_rebuild() {
+    let (world, mut h) = fixture();
+    let rev = world_rev::of(&world);
+    h.execute(&world, CreateSetup::new(&world, None, None).expect("setup"));
+    assert_ne!(world_rev::of(&world), rev);
